Definition src_ok (i : nat) (pv lv : PB4.pvals2) (d : PSM2.delta) (cls : PSM6.dcls) (E1 E' : env) (M' : mem) (pst : PML.pstate) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 9 "S10;A1;o2;Y6;00;Y3;0;A2;k23;r3;A1;k237;r7;A1;k225;r7;A2;i15;i7;i7;A2;k23;r3;A1;k233;r7;A2;k261;vSCFG_P;vI;A1;k263;r6;A1;k237;r8;A3;i11;i7;#2;A1;o20;Y3;7;Li;Ri45;Lpv;Ri218;Llv;Ri218;Ld;Ri219;Lcls;Ri257;LE1;Ri0;LE';Ri0;LM';RP~RA1;i1;#0;A1;i3;A1;i1;A1;o2;#1;Lpst;Ri105;A2;i26;A3;k109;r2;A2;k258;vSCFG_P;vI;r1;A2;i26;A1;k251;r1;A2;i26;A3;k259;vSCFG_P;vI;r1;A2;i26;A2;k252;r1;A2;k260;vSCFG_P;vI;A2;i26;A3;i11;i8;A1;k122;r1;o13;A2;i26;A3;i11;i7;A1;k118;r1;#2;A2;i26;A3;i11;i7;A1;k120;r1;A2;k23;r3;#3;A2;i26;A3;i11;A1;i3;#4;A1;k107;r1;A2;k151;#5;#6;A2;i26;A2;i26;A2;k58;A2;k262;vSCFG_P;vI;#5;A2;k58;#5;#6;A2;i26;A3;i11;i7;#5;A2;k113;A2;k23;r4;A1;k233;r8;#7;A2;i26;A2;i26;A2;k58;o59;#7;A2;k58;#7;A1;o20;o74;A2;i26;A3;i11;A1;i4;#4;A2;k264;r4;A4;k96;k265;r9;k266;A1;o60;A2;i15;i6;i6;A1;k267;r1;A2;i26;A2;k268;A2;k269;vSCFG_P;vI;r2;m257;RNLcls;Ri257;pr5;4;A2;i26;A3;i11;i7;#2;A2;k23;r3;#8;A2;i26;P~RA2;i183;A3;i11;i45;r9;k270;A2;i183;A3;i11;i45;r9;k271;A2;i183;A3;i11;i45;r9;k272;A3;i11;i45;r9;k273;A2;k58;A1;k274;r2;A2;k101;#0;A2;k275;r5;N50;A3;i11;i6;#3;A1;k225;r8;#9;#9;Lkk;Ri7;A3;i11;i7;A2;k23;r4;#8;A1;o20;Y4;1;").
Lemma sr_cls : forall i c ps pv lv d cls, PSM6.dclass i c ps pv lv d = Some cls ->
  (kind_of i = KInv /\ PSM5.same_state d = true /\ cls = PSM6.D0 /\ (PSM6.all_in (SR.ps_cells ps) (PB4.pv_st pv) (fun s => negb (s =? 17)) || PSM2.foot2 c)%bool = true) \/
  (kind_of i = KInv /\ cls = PSM6.D1 /\ PSM2.d_st d = Some (ELit 15) /\ PSM2.d_sst d = Some 0 /\ PSM2.d_nst d = None /\ PSM2.d_more d = None /\ PSM2.d_done d = None /\
     PSM2.d_clr d = true /\ PSM6.all_in (SR.ps_cells ps) (PB4.pv_st pv) PSM6.plainb = true) \/
  (kind_of i = KVec /\ cls = PSM6.D2 /\ PSM2.d_st d = Some (ELit 15) /\ PSM2.d_sst d = Some 0 /\ PSM2.d_nst d = None /\ PSM2.d_more d = None /\ PSM2.d_done d = None /\
     PSM2.d_clr d = true /\ CAX.cell_at (CC.cp_know c) (EVar 2) (-120) 1 = Some (ELit 16) /\
     PSM6.all_in (SR.ps_cells ps) (PB4.pv_st pv) (fun s => (s =? 9) || (s =? 10))%bool = true) \/
  (kind_of i = KPushB /\ exists kk blo bhi, cls = PSM6.D3 kk /\ PSM2.d_st d = Some (ELit 17) /\ PSM2.d_sst d = None /\ PSM2.d_nst d = Some kk /\ PSM2.d_more d = None /\
     PSM2.d_done d = None /\ PSM2.d_clr d = false /\ PSM2.rng_of (SR.ps_cells ps) (PSM2.pushed_of i) = (blo, bhi) /\
     (PSM6.all_in (SR.ps_cells ps) (PB4.pv_st pv) PSM6.plainb && PSM2.foot2 c && (PSM2.d_adv d =? 1) && APC.expr_vars_lt (CC.cp_nx c) (PSM2.pushed_of i)
      && ((kk =? 0) && (blo =? 45) && (bhi =? 45) || (kk =? 1) && (blo =? 48) && (bhi =? 48) || (kk =? 2) && (49 <=? blo) && (bhi <=? 57)))%bool = true).
Proof.
  intros i c ps pv lv d cls H. unfold PSM6.dclass in H. cbv zeta in H.
  repeat (match type of H with
          | context [match ?x with _ => _ end] => first [is_var x; destruct x | let Hq := fresh "Hq" in destruct x eqn:Hq]
          end; try discriminate H).
  all: injection H as <-.
  all: first [ left; repeat split; assumption
             | right; left; repeat split; assumption
             | right; right; left; repeat split; assumption
             | right; right; right; split; [first [reflexivity | assumption]|];
               match goal with
               | Hr : PSM2.rng_of _ _ = (?lo, ?hi), Hn : PSM2.d_nst _ = Some ?kk |- _ => exists kk, lo, hi; repeat split; assumption
               end ].
Qed.
Lemma sr_ics : forall x, In x PMCUR.ICS <-> (x = 7 \/ x = 9 \/ x = 10 \/ x = 11 \/ x = 12 \/ x = 13 \/ x = 16).
Proof.
  intros x. unfold PMCUR.ICS, PML.ST_EXPECT_COMMA_OR_END, PML.ST_EXPECT_MEMBER_NAME_OR_END, PML.ST_EXPECT_MEMBER_NAME, PML.ST_EXPECT_COLON,
    PML.ST_EXPECT_VALUE_OR_END, PML.ST_EXPECT_VALUE, PML.ST_MEMBER_NAME. cbn [In]. split; intros Hx; lia.
Qed.
Lemma sr_cl : forall ps0 st sst nst bd bc bp buf w stk, PSI.CL I ps0 -> PML.ps_more ps0 = true ->
  (In st PMCUR.ICS -> In (PML.ps_st ps0) PMCUR.ICS) -> (forall x, In x stk -> In x PMCUR.ICS -> In (PML.ps_st ps0) PMCUR.ICS \/ In x (PML.ps_stack ps0)) ->
  PSI.CL I (PML.PS st sst nst true bd (PML.ps_level ps0) stk (PML.ps_sb ps0) (PML.ps_scap ps0) bc bp buf w).
Proof.
  intros ps0 st sst nst bd bc bp buf w stk (H1 & H2) Hm Hst Hstk. split.
  - intros _ [Q|(x & Qx & Qi)].
    + apply H1; [exact Hm | left; exact (Hst Q)].
    + destruct (Hstk x Qx Qi) as [Q|Q].
      * apply H1; [exact Hm | left; exact Q].
      * apply H1; [exact Hm | right; exists x; split; assumption].
  - intros _. exact (H2 Hm).
Qed.
Lemma sr_np : forall kk b, (kk = 0 /\ b = 45) \/ (kk = 1 /\ b = 48) \/ (kk = 2 /\ 49 <= b <= 57) -> PML.num_prefix kk [b].
Proof.
  intros kk b H. exists kk. split; [|left; reflexivity]. cbn [PML.nl_run]. unfold PML.nl_step. rewrite Z.eqb_refl.
  destruct H as [[-> ->]|[[-> ->]|[-> Hb]]]; [reflexivity|reflexivity|].
  replace (b =? 45) with false by (symmetry; apply Z.eqb_neq; lia). replace (b =? 48) with false by (symmetry; apply Z.eqb_neq; lia).
  unfold PML.is_dig. replace ((48 <=? b) && (b <=? 57))%bool with true by (symmetry; apply andb_true_iff; split; apply Z.leb_le; lia). reflexivity.
Qed.
Lemma sr_kk : forall kk blo bhi x, blo <= x <= bhi ->
  ((kk =? 0) && (blo =? 45) && (bhi =? 45) || (kk =? 1) && (blo =? 48) && (bhi =? 48) || (kk =? 2) && (49 <=? blo) && (bhi <=? 57))%bool = true ->
  (kk = 0 /\ x = 45) \/ (kk = 1 /\ x = 48) \/ (kk = 2 /\ 49 <= x <= 57).
Proof.
  intros kk blo bhi x Hx H. apply orb_prop in H as [H|H]; [apply orb_prop in H as [H|H]|].
  - apply andb_prop in H as [H H3]. apply andb_prop in H as [H1 H2]. apply Z.eqb_eq in H1, H2, H3. lia.
  - apply andb_prop in H as [H H3]. apply andb_prop in H as [H1 H2]. apply Z.eqb_eq in H1, H2, H3. lia.
  - apply andb_prop in H as [H H3]. apply andb_prop in H as [H1 H2]. apply Z.eqb_eq in H1. apply Z.leb_le in H2, H3. lia.
Qed.
Lemma pt_src : forall i c k ps1 pc pv lv pe ce d cls, is_leaf i c k ps1 (CC.TOther pc) -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> PSM6.dclass i c ps1 pv lv d = Some cls ->
  PSM2.rng_is (SR.ps_cells ps1) (PB4.pv_more pv) 1 = true ->
  forall E1 E' R' (M1 M' : mem) model1, env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> HAMB i E1 M' model1 -> XI i E1 M1 ->
  exists pst, src_ok i pv lv d cls E1 E' M' pst.
Proof.
intros i c k ps1 pc pv lv pe ce d cls Hleaf Hld Hcls Hrng E1 E' R' M1 M' model1 Hag0 Hag Hlf HH HX.
unfold src_ok.
pose proof (PSB.lview_vw _ _ _ _ _ _ _ (PSX.ldelta_lview _ _ _ _ _ _ _ _ Hld)) as Hvw.
pose proof (PSB.leaf_know I c ps1 E' R' M1 M' Hlf) as HKc.
assert (HGR0 : mem_grows M' M') by (intros x0 Hx0; exact Hx0).
pose proof (PSI.WIN I) as (W0 & _).
pose proof (PSB.CEIL I) as HCEIL.
destruct (PSB.bls2 _ _ _ _ _ _ _ _ Hleaf Hvw) as (sbe & sce & HBL).
destruct (PSB.own_blocks I i E1 M' model1 pe ce sbe sce HH HBL) as ((C0 & C1 & C2 & C3 & C4) & _).
unfold PSI.XI in HX. destruct HX as (X1 & X2 & X3 & HX).
destruct (sr_cls _ _ _ _ _ _ _ Hcls) as [(K1 & Yss & -> & Yd)|[(K1 & -> & Dst & Dsst & Dnst & Dmore & Ddone & Dc & Ypl)|[(K1 & -> & Dst & Dsst & Dnst & Dmore & Ddone & Dc & Hx16 & Y910)|(K1 & kk & blo & bhi & -> & Dst & Dsst & Dnst & Dmore & Ddone & Dc & Hr & Y3)]]].
- rewrite K1, Hvw in HX. destruct HX as (bm & bd & stack & buf & HC & HS & HW & HB & HWS & HR & HE).
  destruct (PSB.leaf_state_g I i c k ps1 _ pv lv pe ce d E1 E' R' M1 M' M' model1 bm bd stack buf Hleaf Hld HH HGR0 Hag Hlf HC)
    as (_ & HK & _ & L1 & L2 & L3 & L4 & L5 & L6 & L7 & (AG1 & AG2 & AG3) & L8 & L9 & L10 & L11 & L12 & L13 & L14 & L15 & L16 & HSB & FR2 & FRI & HPAX & Hden & HEQ).
  pose proof HC as (HC1 & HC2 & HC3 & HC4 & HC5 & HC6 & HC6b & HC7 & HC8 & HC9).
  assert (Hbmt : bm = true) by (apply PSB.b2z_inj1; rewrite <- HC8, <- AG2; exact (PSB.rng_is_sound E' M' _ _ 1 HKc Hrng)). subst bm.
  destruct (PSF.same_state_facts d Yss) as (Dst & Dsst & Dnst & Dmore & Ddone & Dc).
  rewrite Dst in L8. rewrite Dsst in L9. rewrite Dnst in L10. rewrite Dmore in L11. rewrite Ddone in L12. rewrite Dc in L13. cbn [PSB.newv] in L8, L9, L10, L11, L12, L13.
  destruct (HPAX true bd ltac:(rewrite L11; exact HC8) ltac:(rewrite L12; exact HC9)) as (bufm & HPA & Hlen & Hbeq).
  set (psc := PSI.ps_of pv pe ce E1 true bd stack buf) in *.
  assert (HPS : PSI.ps_of lv pe ce E' true bd stack bufm = PSS.upd psc (PML.ps_st psc) (PML.ps_sst psc) (PML.ps_nst psc) (PML.ps_more psc) bd (uv E1 ce) (uv E1 pe) bufm (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend))
    by (rewrite (HEQ true bd bufm), L8, L9, L10; reflexivity).
  assert (Hwl1 : PML.winlen psc = wend - uv E1 (PB4.pv_wptr pv)) by (unfold psc, PSI.ps_of; rewrite HC4; apply PSB.winlen_of; lia).
  assert (Hwl2 : PML.winlen (PSI.ps_of lv pe ce E' true bd stack bufm) = wend - uv E' (PB4.pv_wptr lv)) by (unfold PSI.ps_of; rewrite L5; apply PSB.winlen_of; lia).
  pose proof (PSB.buf_need_range psc HW) as Hbn1.
  exists (PSI.ps_of lv pe ce E' true bd stack bufm).
  split; [exact HPA|].
  split.
  { rewrite HPS. apply PSX.wf_upd_same; [exact HW|]. intros Hn _. apply orb_prop in Yd. destruct Yd as [Yd|Yd].
    - exfalso. pose proof (all_in_sound E' M' _ _ _ HKc Yd) as Q. cbv beta in Q. rewrite AG1 in Q. change (PML.ps_st psc) with (uv E1 (PB4.pv_st pv)) in Hn.
      rewrite Hn in Q. unfold PML.ST_NUMBER in Q. cbn in Q. discriminate Q.
    - exact (Hbeq Dc Hn Yd). }
  split; [rewrite HPS; exact (proj1 HWS)|].
  split.
  { destruct HB as [HB1 HB2]. split; [|exact HB2].
    assert (Hbn : PML.buf_need (PSI.ps_of lv pe ce E' true bd stack bufm) = PML.buf_need psc) by (rewrite HPS; reflexivity).
    rewrite Hbn, Hwl2. rewrite Hwl1 in HB1. change (PML.ps_buf psc) with buf in HB1. change (PML.ps_buf (PSI.ps_of lv pe ce E' true bd stack bufm)) with bufm. lia. }
  split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
  split; [unfold PSI.ps_of; cbn [PML.ps_win]; rewrite L5; reflexivity|].
  split; [lia|]. split; [exact L14|]. split; [exact L15|].
  split; [rewrite Hden; unfold PSI.ps_of, PML.ps_blocks; cbn [PML.ps_bptr PML.ps_bcap PML.ps_sb PML.ps_scap]; rewrite L6, L7, L2, L4; reflexivity|].
  split; [exact (PSB.ls_frame M1 M' g FRI (PSI.iHG I) HS)|].
  split; [rewrite L8, AG1; reflexivity|]. split; [intros Hi; rewrite HPS; exact (HR Hi)|]. exact (ldelta_nst _ _ _ _ _ _ _ _ Hld Dnst).
- rewrite K1, Hvw in HX. destruct HX as (bm & bd & stack & buf & HC & HS & HW & HB & HWS & HR & HE).
  destruct (PSB.leaf_state_g I i c k ps1 _ pv lv pe ce d E1 E' R' M1 M' M' model1 bm bd stack buf Hleaf Hld HH HGR0 Hag Hlf HC)
    as (_ & HK & _ & L1 & L2 & L3 & L4 & L5 & L6 & L7 & (AG1 & AG2 & AG3) & L8 & L9 & L10 & L11 & L12 & L13 & L14 & L15 & L16 & HSB & FR2 & FRI & HPAX & Hden & HEQ).
  pose proof HC as (HC1 & HC2 & HC3 & HC4 & HC5 & HC6 & HC6b & HC7 & HC8 & HC9).
  assert (Hbmt : bm = true) by (apply PSB.b2z_inj1; rewrite <- HC8, <- AG2; exact (PSB.rng_is_sound E' M' _ _ 1 HKc Hrng)). subst bm.
  rewrite Dst in L8. rewrite Dsst in L9. rewrite Dnst in L10. rewrite Dmore in L11. rewrite Ddone in L12. rewrite Dc in L13. cbn [PSB.newv] in L8, L9, L10, L11, L12, L13.
  rewrite PB2.uv_lit in L8 by lia.
  destruct (HPAX true bd ltac:(rewrite L11; exact HC8) ltac:(rewrite L12; exact HC9)) as (bufm & HPA & Hlen & _).
  rewrite L13 in Hlen. destruct bufm as [|b0 bufm]; [|cbn [length] in Hlen; lia].
  set (psc := PSI.ps_of pv pe ce E1 true bd stack buf) in *.
  pose proof HW as (HW1 & HW2 & HW3 & HW4 & _).
  pose proof (all_in_sound E' M' _ _ _ HKc Ypl) as Q. rewrite AG1 in Q. destruct (plainb_ok _ Q) as (Pcc & P15).
  assert (Hwl1 : PML.winlen psc = wend - uv E1 (PB4.pv_wptr pv)) by (unfold psc, PSI.ps_of; rewrite HC4; apply PSB.winlen_of; lia).
  assert (Hwl2 : PML.winlen (PSI.ps_of lv pe ce E' true bd stack []) = wend - uv E' (PB4.pv_wptr lv)) by (unfold PSI.ps_of; rewrite L5; apply PSB.winlen_of; lia).
  pose proof (PSB.buf_need_range psc HW) as Hbn1.
  exists (PSI.ps_of lv pe ce E' true bd stack []).
  split; [exact HPA|].
  split.
  { rewrite (HEQ true bd []), L8, L9.
