Lemma pt_facts : forall i c k ps1 pc j scr ereg, is_leaf i c k ps1 (CC.TOther pc) -> CH2.ret_of G.RETS i k = Some j -> pt_of pc = Some (scr, ereg) ->
  exists cj ci pv lv pe ce d cls, nth_error G.CPS j = Some cj /\ SR.ps_pc ps1 = pc /\ PB2.ptrans_chkc GT.NF G.HDECL Eb 0 Pb 0 scr Vb 0 ereg c ps1 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci /\
    PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) /\ PSM6.dclass i c ps1 pv lv d = Some cls /\ kind_of j = KPt /\ PSM2.cur_cut j = PSM6.is_cur pc /\ PSI.skip_cut j = Z.eqb pc PML.PC_SKIP_SPACE /\
    PSM2.rng_is (SR.ps_cells ps1) (PB4.pv_more pv) 1 = true /\ PB.has (SR.ps_cells ps1) (KWord (SA Vb 0) 8 (ELit PML.VT_VISITOR)) = true /\ PB.has (SR.ps_cells ps1) (KWord (SA Eb 0) 4 (ELit 0)) = true /\
    (PSM2.in_loop j = true \/ PSM2.under0 j = true) /\ Z.eqb (PSM2.reent_pc j) L2PC = Z.eqb pc PML.PC_BEGIN_MEMBER /\ (PSM2.under0 j = true -> (Z.eqb pc PML.PC_END_INT || Z.eqb pc PML.PC_END_FRAC)%bool = true) /\
    exists slack, slack = (if PSM2.in_loop j then PSM6.loop_chk c ps1 pv d (CC.cp_nx cj - APC.NCS - 5)%nat else None) /\ (PSM2.in_loop j = true -> isSome slack = true) /\
                  PSM6.callee_chk pc i j c ps1 pv lv cls slack (PSM2.d_adv d) = true.
