     forall R2 (M2 : mem) ps2 code E2, PAout pst M2 P ps2 -> PML.wf_ps ps2 -> (code <> 0 -> PML.ps_more ps2 = false) -> Rel pst ps2 code R2 -> (code = 0 -> PSI.CX I ps2 M2) ->
        env_agree (CC.cp_nx cj - APC.NCS - 5) E' E2 -> ev E2 (CC.cp_nx cj - APC.NCS + 4) = getr R2 10%bv -> post_ok j ps2 code E2 M2) ->
  CC.leaf_ok (hl_segs L) G.CPS AMB3 K PML.fp_ok i c ps1.
Proof.
intros ereg i c k ps1 j cj ci pv lv pe ce d cls IL Hret Hcj Hpc Hng Hchk Hld Hcls Hkj Hrng Hvt Hec USER.
assert (Hcutj : PSM2.cutn j = cj) by (unfold PSM2.cutn; exact (nth_error_nth _ _ _ Hcj)).
assert (HNF5 : (GT.NF <= CC.cp_nx cj - APC.NCS - 5)%nat) by (pose proof (PSF.call_nf _ _ _ _ _ _ IL Hret) as Q; rewrite Hng, Hcutj in Q; exact Q).
pose proof PSI.NF32 as HNF32.
apply (PB6.ptrans_leaf_ok2 L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS Cred (PSI.STKF I) PSI.SCRP PSI.NF32 (PSI.U2 I) (PSI.TP0 I)
         (PSI.W_OK I) (PSI.CRS_OK I) (PSI.WRS_OK I) (PSI.IMG_OK I) G.CPS G.TAGS G.RETS K (PSI.iHKnil I) XI (PSI.DEF0 I)
         Eb 0 ltac:(vm_compute; reflexivity) E (PSF.EADDR I) (PSF.EOBJ I) g (PSI.iHG I) Pb 0 ltac:(vm_compute; reflexivity) P PADDR V OBJS
         Vb 0 ltac:(vm_compute; reflexivity) VADDR WPARC_in CPC CSCR WFin BBin PAin PAout Args Rel CALLEE PAOUT_CAP B kx bx ereg i c k ps1 j cj ci IL Hret Hcj Hpc Hchk).
intros E1 E' R' M1 M' model1 cr HagE' Hsr Hnx Hag HLF HRL HA' HX HIH HCr.
assert (X1 : L5.defined M1 (sp - CH.hd_scr G.HDECL) (CH.hd_scr G.HDECL)) by (unfold PSI.XI in HX; exact (proj1 HX)).
destruct (PSF.call_common I i c k ps1 _ j IL Hret E1 E' R' M1 M' HagE' HLF HX) as (CM1 & CM2).
destruct (pt_src i c k ps1 CPC pv lv pe ce d cls IL Hld Hcls Hrng E1 E' R' M1 M' model1 HagE' Hag HLF HA' HX) as (pst & HS).
pose proof (USER E1 E' R' M1 M' model1 pst HagE' Hag HLF HRL HA' HX HS) as (UA & UPA & UWF & UBB & UPOST).
unfold src_ok in HS. destruct HS as (HPA & HWF & HCL & HBB & HMO & HST & HNST & HWIN & HWP & HADV & HADR & HDEN & HLS & _).
destruct (PSB.FRZ I E' HagE') as (F1 & F2 & F3 & _).
pose proof (PSB.leaf_know I c ps1 E' R' M1 M' HLF) as HKc.
pose proof (PSI.OBJR I) as (O1 & O2 & O3 & O4 & O5 & O6 & O7).
assert (HVT : PML.u64 M' V PML.VT_VISITOR).
{ pose proof (PB2.kword64_elim E' M' _ _ V (PB.has_ok E' M' _ _ HKc Hvt)) as T. rewrite PB2.uv_lit in T by (unfold PML.VT_VISITOR; clear; lia). apply T.
  unfold estart. cbn [a_base a_off]. fold (uv E' Vb). rewrite F2. clear; lia. }
assert (HdV' : L5.defined M' V 48) by exact (PSB.amb_def I i E1 M' model1 V 48 HA' (proj2 (PSI.iHVIS I)) ltac:(clear - O4 O5; lia)).
pose proof (PSI.iHEC I) as (_ & HEd & _).
assert (HdE' : L5.defined M' E 16) by exact (PSB.amb_def I i E1 M' model1 E 16 HA' HEd ltac:(clear - O6 O7; lia)).
exists pst. split.
{ destruct (PSF.other_facts _ _ _ _ _ IL) as (_ & F2b). rewrite (CH2.den_agree _ E1 E' _ Hag F2b). exact HDEN. }
split.
{ unfold PB6.ptrans_pre. split; [exact UA|]. split; [exact UPA|]. split; [exact UWF|].
  split.
  { apply (win_ok_eq M' pst (PML.PS 0 0 0 true true 0 [] 0 0 0 0 [] (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend))); [rewrite HWIN; reflexivity|].
    apply (PSX.win_ok_of I); [exact (PSX.win_def I i E1 M' model1 HA') | exact HWP]. }
  split; [exact UBB|].
  split; [exact (conj HVT HdV')|].
  split; [exact (PSX.ecell0 I E' M' _ HKc HagE' Hec HdE')|].
  split; [exact HLS|].
  pose proof HWF as (_ & _ & _ & HW4 & _). apply (proj1 (PSI.cred_of_blocks I i E1 cr pst HDEN HW4)). exact HCr. }
intros R2 M2 cr2 ps2 code g' E2 (HPOST & HCUR) Hag2 Hcode HR10 Hden2 HPRES.
unfold PB6.ptrans_post in HPOST.
destruct HPOST as (QPA & QWF & QWIN & QBB & QEC & QMO & QLS & QG & QPC & QREL).
destruct QWF as (QWF1 & QLV).
assert (Hag2' : env_agree (CC.cp_nx cj - APC.NCS - 5) E' E2) by (rewrite <- Hnx; exact Hag2).
assert (HR10' : ev E2 (CC.cp_nx cj - APC.NCS + 4) = getr R2 10%bv).
{ replace (CC.cp_nx cj - APC.NCS + 4)%nat with (CH2.ci_nx ci + 9)%nat by (rewrite Hnx; lia). exact HR10. }
assert (HWLE : PMCUR.win_le (PML.ps_win ps) (PML.ps_win pst)) by (rewrite HWIN; apply win_le_of; exact HWP).
pose proof (UPOST R2 M2 ps2 code E2 QPA QWF1 QMO QREL (fun H0 => cx_post pst ps2 code M2 HCL HMO HWLE QLV HCUR H0) Hag2' HR10') as HPO.
unfold post_ok in HPO. destruct HPO as (cw & HPA2 & HCW & HSK & HC0).
pose proof QWF1 as (_ & _ & _ & QW4 & _).
split.
- unfold PSI.XI. split.
  { pose proof (PSI.STKF I) as (_ & S2 & S3 & S4). pose proof PSI.SCRP as S5.
    apply (PSF.hpres_def I _ _ _ _ M' M2 _ _ HPRES).
    - exact (PSB.grows_def M1 M' _ _ (CC.lf_grows _ _ _ _ _ _ _ HLF) X1).
    - lia.
    - lia. }
  split; [exact CM1|]. split; [exact CM2|].
  rewrite Hkj. change (PSI.pt_post I j E2 M2). unfold PSI.pt_post. cbv zeta.
  exists ps2, code, g', cw.
  split; [exact HPA2|]. split; [exact QWF1|]. split; [exact QWIN|]. split; [exact QBB|]. split; [exact QEC|]. split; [exact QMO|].
  split; [exact QLS|]. split; [exact QG|]. split; [rewrite Hcutj, <- Hnx; exact Hcode|]. split; [exact Hden2|].
  split; [exact HSK|]. split; [exact HCW|]. exact HC0.
- apply (proj2 (PSI.cred_of_blocks I j E2 cr2 ps2 Hden2 QW4)). exact QPC.
Qed.
End PT.

