Lemma leaf_container : forall pc Rel, (Z.eqb pc PML.PC_BEGIN_OBJECT || Z.eqb pc PML.PC_BEGIN_ARRAY || Z.eqb pc PML.PC_END_OBJECT || Z.eqb pc PML.PC_END_ARRAY)%bool = true ->
  PMS.ptrans L HI pc PF_SCR (fun R0 M0 P0 V0 E0' ps0 => PMS.std_args R0 M0 P0 V0 E0' ps0 /\ PML.ps_more ps0 = true /\ ~ PML.comment_or_cr (PML.ps_st ps0) /\ PML.ps_st ps0 <> PML.ST_STRING) Rel ->
